from blipshell.utils import chunked, retry_with_backoff
import time
from unittest.mock import MagicMock, patch


def test_chunked_splits_evenly():
    assert list(chunked([1, 2, 3, 4], 2)) == [[1, 2], [3, 4]]


def test_retry_backoff_doubles():
    @retry_with_backoff(max_retries=3, initial_delay=0.1)
    def failing_func():
        raise ValueError("Failed")

    with patch('time.sleep') as mock_sleep:
        try:
            failing_func()
        except ValueError:
            pass

        # Check that sleep was called with doubling delays
        assert mock_sleep.call_count == 3
        assert mock_sleep.call_args_list[0][0][0] == 0.1
        assert mock_sleep.call_args_list[1][0][0] == 0.2
        assert mock_sleep.call_args_list[2][0][0] == 0.4

